import{_ as o,C as r,o as d,c as s,aj as a,E as i}from"./framework.js";const u=JSON.parse('{"title":"控制面板 | Cms / Site | Documentation","description":"控制面板 in Kooboo: 点击站点 管理 后首先看到的概览页，用于快速了解站点资源占用、访问概况，并跳转到常用功能。","frontmatter":{"title":"控制面板 | Cms / Site | Documentation","description":"控制面板 in Kooboo: 点击站点 管理 后首先看到的概览页，用于快速了解站点资源占用、访问概况，并跳转到常用功能。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/cms/site/dashboard.html"}]]},"headers":[],"relativePath":"zh/cms/site/dashboard.md","filePath":"cms/site/dashboard.md","lastUpdated":1780283318000}'),n={name:"zh/cms/site/dashboard.md"};function l(h,t,c,b,p,m){const e=r("DocImage");return d(),s("div",null,[t[0]||(t[0]=a('<h1 id="控制面板" tabindex="-1">控制面板 <a class="header-anchor" href="#控制面板" aria-label="Permalink to &quot;控制面板&quot;">​</a></h1><blockquote><p>菜单：左侧顶栏 <strong>主页</strong>（进入站点后默认页）<br> 深链：<code>/_Admin/site?SiteId={站点GUID}</code></p></blockquote><p>点击站点 <strong>管理</strong> 后首先看到的概览页，用于快速了解站点资源占用、访问概况，并跳转到常用功能。</p><div class="tip custom-block"><p class="custom-block-title">前置</p><p>已完成 <a href="./../getting-started/login-and-site-list.html">登录与站点列表</a> 并进入某一站点。</p></div><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><ol><li>在 <strong>我的站点</strong> 中点击目标站点的 <strong>管理</strong>。</li><li>地址栏为 <code>/_Admin/site?SiteId=...</code>（无子路径时即为控制面板）。</li><li>之后可随时点左侧顶栏 <strong>主页</strong> 图标返回本页。</li></ol>',6)),i(e,{src:"/cms/site/dashboard.png",alt:"dashboard 总览",width:"1120"}),t[1]||(t[1]=a('<h2 id="页面布局" tabindex="-1">页面布局 <a class="header-anchor" href="#页面布局" aria-label="Permalink to &quot;页面布局&quot;">​</a></h2><p>页面大致分为<strong>左侧主栏</strong>与<strong>右侧信息栏</strong>。</p><h3 id="最近访问" tabindex="-1">最近访问 <a class="header-anchor" href="#最近访问" aria-label="Permalink to &quot;最近访问&quot;">​</a></h3><p>展示你近期在后台打开过的功能入口，点击可快速回到对应页面（如基础设置、商品管理、域名管理等）。</p><h3 id="我的资源" tabindex="-1">我的资源 <a class="header-anchor" href="#我的资源" aria-label="Permalink to &quot;我的资源&quot;">​</a></h3><p>以表格汇总站点内各类资源的<strong>数量</strong>与<strong>占用大小</strong>，例如：</p><table tabindex="0"><thead><tr><th>常见类型</th><th>说明</th></tr></thead><tbody><tr><td>页面</td><td>站点页面数量</td></tr><tr><td>组件（View）</td><td>可复用视图</td></tr><tr><td>内容</td><td>内容条目</td></tr><tr><td>代码</td><td>CodeBlock 等</td></tr><tr><td>图片</td><td>媒体库中的图片资源</td></tr><tr><td>脚本 / 样式</td><td>站点 Script、Style</td></tr></tbody></table><p>便于判断站点体量，再决定从哪一类资源下手维护。</p><h3 id="访问统计-访客日志" tabindex="-1">访问统计（访客日志） <a class="header-anchor" href="#访问统计-访客日志" aria-label="Permalink to &quot;访问统计（访客日志）&quot;">​</a></h3><p>柱状图展示一段时间内的**页面浏览量（PV）**趋势。详细访客分析见 <strong>运维中心 → 访问统计</strong>（与本文概览数据口径可能不同）。</p><h3 id="热门页面-热门来源" tabindex="-1">热门页面 / 热门来源 <a class="header-anchor" href="#热门页面-热门来源" aria-label="Permalink to &quot;热门页面 / 热门来源&quot;">​</a></h3><ul><li><strong>热门页面</strong>：访问量较高的页面路径排行。</li><li><strong>热门来源</strong>：访客从哪些引荐来源进入站点。</li></ul><p>用于运营侧快速发现流量集中在哪些页面、渠道。</p><h3 id="最近编辑" tabindex="-1">最近编辑 <a class="header-anchor" href="#最近编辑" aria-label="Permalink to &quot;最近编辑&quot;">​</a></h3><p>列出近期在后台修改过的对象，便于接续未完成的工作。</p><h3 id="右侧-站点信息" tabindex="-1">右侧：站点信息 <a class="header-anchor" href="#右侧-站点信息" aria-label="Permalink to &quot;右侧：站点信息&quot;">​</a></h3><p>显示当前站点名称、类型、创建时间、绑定域名、授权用户等摘要。域名与成员权限的详细配置在 <strong>站点设置</strong> 中完成。</p><h3 id="右侧-文档与产品动态" tabindex="-1">右侧：文档与产品动态 <a class="header-anchor" href="#右侧-文档与产品动态" aria-label="Permalink to &quot;右侧：文档与产品动态&quot;">​</a></h3><p>提供 Kooboo 相关文档入口与产品新闻，与站点配置无直接关系，可按需浏览。</p><h2 id="与开发文档的关系" tabindex="-1">与开发文档的关系 <a class="header-anchor" href="#与开发文档的关系" aria-label="Permalink to &quot;与开发文档的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>在控制面板看到</th><th>进一步阅读</th></tr></thead><tbody><tr><td>我的资源 → 页面 / 组件</td><td><a href="./pages.html">页面</a> · <a href="/kb-docs/zh/templateEngine/page/">模板引擎</a></td></tr><tr><td>我的资源 → 图片</td><td><a href="./media.html">媒体库</a></td></tr><tr><td>我的资源 → 内容</td><td><a href="./../content/">内容模块</a></td></tr></tbody></table>',21))])}const _=o(n,[["render",l]]);export{u as __pageData,_ as default};
